(function(){
'use strict';
const M=PulseModel,S=M.schemas,$=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settingsOpen=false,importKey='actions',importGeneration=0;
const STORE='pulse-5g-updates-v1',PREVIOUS=STORE+'-previous';
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${PulseIcons[n]||PulseIcons.file}</svg>`;
const btn=(label,action,ico,cls='')=>`<button type="button" class="${cls}" data-action="${action}">${ico?icon(ico):''}${e(label)}</button>`;
const tracks=['actions','risks','rfp','milestones','escalations'];
const pages=[...tracks,'assets','team','raci'];
const aboutTitles=['Coverage','General Architecture','Capabilities','Why Private 5G','POC Sites','Operational Dashboard'];
const pageInfo=k=>S[k]||{title:'Network Assets',short:'Network assets',icon:'network',description:'The physical network and device landscape.'};
let db,storageIssue='',route='agenda',query='',filter='',showDeleted=false,theme='dark',aboutLang='en',pendingExcel=null,lastFocus=null;
const views={milestones:'categories'},sorts={};let navDirection=1,categoryPosition=0;const I=PulseInsights;
const orderedPages=['agenda',...pages,...aboutTitles.map((_,i)=>'about-'+(i+1))];
const navLabels=['Agenda','Actions','Risks','RFPs','Milestones','Escalations','Network Assets','Team','RACI'];
let navSection='';
function syncNav(){
 const about=route.startsWith('about-'),section=about?'brief':'updates',rail=$('#nav-rail');
 if(navSection!==section){navSection=section;const entries=about?aboutTitles.map((label,i)=>({key:'about-'+(i+1),label:['Coverage','Architecture','Capabilities','Why 5G','POC Sites','Dashboard'][i],ico:['network','grid','shield','file','flag','grid'][i]})):['agenda',...pages].map((k,i)=>({key:k,label:navLabels[i],ico:k==='agenda'?'home':pageInfo(k).icon}));
 const jump=`<a class="section-jump" href="#${about?'agenda':'about-1'}">${icon(about?'left':'arrow')}<span>Go to Project ${about?'Updates':'Brief'}</span></a>`;
 rail.innerHTML=(about?jump:'')+entries.map((x,i)=>`<a href="#${x.key}" class="page-link" data-page="${x.key}"><span class="nav-icon">${icon(x.ico)}</span><span class="nav-label">${e(x.label)}</span></a>`).join('')+(!about?jump:'');
 $('.page-navigation').dataset.section=section;PulseFX.navEnter(rail);
 }
 const links=[...rail.querySelectorAll('.page-link')],index=links.findIndex(a=>a.dataset.page===route);
 links.forEach((a,i)=>{const active=i===index;a.classList.toggle('active',active);a.setAttribute('aria-current',active?'page':'false');a.style.setProperty('--distance',Math.min(Math.abs(i-index),4));});
 PulseFX.navFocus(rail,links[index]);
}
function stepPage(delta){navDirection=delta;const idx=orderedPages.indexOf(route);location.hash=orderedPages[(idx+delta+orderedPages.length)%orderedPages.length];}
try{const stored=localStorage.getItem(STORE);db=stored?M.normalize(JSON.parse(stored)):M.normalize(PULSE_SEED);theme=localStorage.getItem(STORE+'-theme')||'dark';}catch(err){db=M.normalize(PULSE_SEED);storageIssue='Local data could not be loaded. Export a snapshot before making changes. '+err.message;}
let loadedRevision=db.modifiedAt||'';let stale=false;
document.body.classList.toggle('light',theme==='light');
function save(){if(stale){toast('This workspace changed in another tab. Reload before editing.');return false;}db.modifiedAt=M.now();try{localStorage.setItem(STORE,JSON.stringify(db));loadedRevision=db.modifiedAt;storageIssue='';$('#save-state').textContent='Saved on this browser';return true;}catch(err){storageIssue='Browser storage unavailable or full. Export JSON to keep your changes.';$('#save-state').textContent='Export JSON to save';const status=$('.agenda-save-state');if(status){status.classList.add('has-warning');status.innerHTML=icon('alert')+'<span>Export a backup to keep changes</span>';}toast(storageIssue);return false;}}
function checkpoint(){try{localStorage.setItem(PREVIOUS,JSON.stringify(db));return true;}catch(_){toast('Could not store a local recovery copy. Export JSON before continuing.');return false;}}
function canEdit(){if(stale){toast('Data changed in another tab. Reload this page first.');return false;}return true;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4800);}
function date(s){if(!s)return 'Not set';return new Date(s.length===10?s+'T12:00:00Z':s).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dubai'});}
function timestamp(s){return new Date(s).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Dubai'})+' GST';}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;($('#modal').open?$('#modal'):document.body).appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);}
function filename(ext){return 'Pulse-5G-Updates-'+new Date().toISOString().replace(/[:.]/g,'-').slice(0,19)+'.'+ext;}
function exportJSON(){const snapshot={...db,exportedAt:M.now()};download(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),filename('json'));toast('Full snapshot exported. Keep it for your next session.');}
function active(k){return M.active(db,k);}
function stat(value,label,ico){return `<div class="stat"><div class="stat-icon">${icon(ico)}</div><div><strong>${e(value)}</strong><span>${e(label)}</span></div></div>`;}
function oldBadge(r){const text=r.status||r.category||'';return `<span class="badge ${M.finished(r)?'done':text==='Open'||text==='Escalation'?'risk':''}">${e(text||'Not set')}</span>`;}
function heading(k,actions='',visual=''){const s=pageInfo(k);return `<div class="page-heading${visual?' with-visual':''}"><div class="page-title"><span class="page-glyph">${icon(s.icon)}</span><div><div class="eyebrow">PULSE 5G / ${String(pages.indexOf(k)+1).padStart(2,'0')}</div><h1>${e(s.title)}</h1></div></div>${visual}<div class="button-row">${btn('Export','export-page','excel','page-export')}${actions}</div></div>`;}
function closeMenu(){}
function render(){
 PulseFX.cleanup();syncNav();$('#main').dataset.page=route;
 const about=route.startsWith('about-');$('#main').hidden=about;$('#about-view').hidden=!about;
 if(about){const i=Number(route.split('-')[1]);$('#about-title').textContent=aboutTitles[i-1];document.title='Pulse 5G | '+aboutTitles[i-1];sendAbout();return;}
 document.title='Pulse 5G | '+(route==='agenda'?'Project Overview':pageInfo(route).title);
 $('#main').innerHTML=(storageIssue?`<div class="warning-note">${e(storageIssue)} ${btn('Open Settings','settings','gear')}</div>`:'')+(route==='agenda'?agenda():route==='assets'?assets():route==='team'?team():route==='raci'?raci():tracker(route));
 $('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');bindPage();PulseFX.enter($('#main'),navDirection);
}
function badge(r){return `<span class="badge tone-${I.tone(r)}">${e(r.status||r.category==='Escalation'&&r.category||r.category==='Approval'&&r.category||'Confirm status')}</span>`;}
function donut(value,total,label,cls='success',animated=false){const percent=total?Math.round(value/total*100):0;return `<div class="donut tone-${cls}" style="--p:${percent}" role="img" aria-label="${e(label)}: ${value} of ${total}, ${percent}%"><svg viewBox="0 0 100 100"><circle class="ring-track" cx="50" cy="50" r="40"/><circle style="opacity:${percent?1:0}" class="ring-value" cx="50" cy="50" r="40" pathLength="100" stroke-dasharray="${percent} 100"/></svg><span><b>${animated?`<span class="metric-number" data-count="${percent}">${percent}</span>`:percent}%</b><small>${e(label)}</small></span></div>`;}
function segments(k,rows){const options=k==='escalations'?['Escalation','Approval']:k==='risks'?['Open','Closed']:['Not Started','In Progress','Completed',''];return options.map(v=>{const count=rows.filter(r=>(k==='escalations'?r.category:r.status)===v).length;return count?`<span class="tone-${I.tone(k==='escalations'?{category:v}:{status:v})}" style="flex:${count}" title="${e(v||'Unconfirmed')}: ${count}" aria-label="${e(v||'Unconfirmed')}: ${count}"></span>`:'';}).join('');}
function feed(){const all=I.projectUpdates(db).slice(0,35);return all.length?all.map(u=>`<article class="feed-entry tone-${I.tone(u.record)}"><div class="feed-type">${icon(S[u.key].icon)}<span>${e(S[u.key].short)}</span>${u.record.status||u.record.category==='Approval'||u.record.category==='Escalation'?badge(u.record):''}</div><button class="feed-name" data-detail="${e(u.recordId)}" data-key="${u.key}">${e(u.name)}</button><p>${e(u.text)}</p><time>${e(timestamp(u.at))}${u.author?' · '+e(u.author):''}</time></article>`).join(''):`<div class="feed-empty"><span class="empty-glyph">${icon('decision')}</span><h3>Keep the focus on progress</h3><p>Written project updates appear here. Add a note to any record to share progress or a decision.</p><a href="#actions">Open action points ${icon('arrow')}</a></div>`;}
function countText(value){const parts=String(value).split(' / ');return `<span class="metric-number" data-count="${e(parts[0])}" style="min-width:${parts[0].length}ch">${e(parts[0])}</span>${parts.length>1?`<span class="metric-total"> / ${e(parts[1])}</span>`:''}`;}
function agendaCard(k){
 const rows=S[k]?active(k):[],total=rows.length,complete=rows.filter(M.finished).length,open=rows.filter(r=>r.status==='Open').length,unknown=rows.filter(r=>!r.status).length,assigned=rows.filter(r=>r.owner?.trim()).length,accountable=rows.filter(r=>[0,1,2,3].some(i=>(r['role'+i]||'').includes('A'))).length;
 const art={actions:'assets/imagery/deployment.png',risks:'about/assets/images/slide5-clean/secure-private-v49.webp',rfp:'assets/imagery/optical-core.png',milestones:'assets/imagery/radio-deployment.png',escalations:'about/assets/images/backgrounds/architecture-uae.webp',assets:'about/assets/images/slide5-clean/infra-dwdm-v49.webp',team:'about/assets/images/slide5-clean/cont-ops-v49.webp',raci:'about/assets/images/slide5-clean/cont-suppliers-v49.webp'}[k];
 const approvals=rows.filter(r=>r.category==='Approval').length,escalations=rows.filter(r=>r.category==='Escalation').length;
 const metric={actions:{value:total-complete,label:'active actions',ratio:complete,caption:'complete',tone:'warning',note:complete+' of '+total+' completed'},risks:{value:open,label:'open risks',ratio:complete,caption:'closed',tone:open?'danger':'success',note:complete+' of '+total+' closed',alert:open?'Open risks require review':''},rfp:{value:total-complete,label:'in progress',ratio:complete,caption:'complete',tone:'info',note:complete+' of '+total+' completed'},milestones:{value:complete+' / '+total,label:'completed',ratio:complete,caption:'complete',tone:'info',note:unknown?unknown+' statuses to confirm':(total-complete)+' remaining',alert:unknown?'Milestone statuses need confirmation':''},escalations:{value:total,label:'decisions required',tone:escalations?'danger':'violet',note:approvals+' approvals · '+escalations+' escalations',alert:total?'Decisions require attention':''},assets:{value:762,label:'mobile sites',tone:'info',note:'365 outdoor · 257 IBS · 140 VVIP'},team:{value:assigned+' / '+total,label:'nominated',ratio:assigned,caption:'nominated',tone:assigned===total?'success':'warning',note:(total-assigned)?(total-assigned)+' roles to nominate':'All roles nominated',alert:assigned<total?'Team nominations incomplete':''},raci:{value:accountable+' / '+total,label:'accountable',ratio:accountable,caption:'assigned',tone:accountable===total?'success':'warning',note:(total-accountable)?(total-accountable)+' need an accountable party':'All assigned',alert:accountable<total?'Accountable parties missing':''}}[k];
 const visual=metric.ratio!==undefined?(total?donut(metric.ratio,total,metric.caption,metric.tone,true):'<span class="agenda-empty-metric" aria-label="No records to measure">—</span>'):`<span class="agenda-object">${icon(k==='assets'?'radio':escalations?'siren':'decision')}</span>`;
 return `<a class="agenda-card compact-card tone-${metric.tone} has-art" href="#${k}"><img class="shortcut-art" src="${art}" alt=""><div class="agenda-card-heading"><span class="agenda-card-icon">${icon(pageInfo(k).icon)}</span><h3>${e(pageInfo(k).short)}</h3><span class="card-open">${icon('arrow')}</span></div><div class="agenda-metric"><div class="agenda-value"><strong aria-label="${e(metric.value)}">${countText(metric.value)}</strong><span>${e(metric.label)}</span></div>${visual}</div><div class="agenda-caption">${metric.alert?`<span class="attention-mark" title="${e(metric.alert)}" aria-label="${e(metric.alert)}">${icon(k==='risks'?'shieldAlert':k==='escalations'?'bellRing':'alert')}</span>`:''}<span>${e(total||k==='assets'?metric.note:'No records yet')}</span></div></a>`;
}
function attentionPanel(){
 const risks=active('risks').filter(r=>r.status==='Open'),decisions=active('escalations'),unconfirmed=active('milestones').filter(r=>!r.status),team=active('team').filter(r=>!r.owner?.trim()),raci=active('raci').filter(r=>![0,1,2,3].some(i=>(r['role'+i]||'').includes('A')));
 const items=[{key:'risks',rows:risks,label:'open '+(risks.length===1?'risk':'risks'),icon:'shieldAlert',tone:'danger'},{key:'escalations',rows:decisions,label:decisions.length===1?'decision required':'decisions required',icon:'bellRing',tone:'violet'},{key:'milestones',rows:unconfirmed,label:unconfirmed.length===1?'milestone status to confirm':'milestone statuses to confirm',icon:'alert',tone:'warning'},{key:'team',rows:team,label:team.length===1?'role to nominate':'roles to nominate',icon:'user',tone:'warning'},{key:'raci',rows:raci,label:'activities without accountability',icon:'alert',tone:'warning'}].filter(x=>x.rows.length);
 return `<section class="analytics-panel attention-panel"><div class="panel-title"><h2>${icon('bellRing')}Needs attention</h2></div><div class="attention-list">${items.map(x=>`<a href="#${x.key}" class="attention-row tone-${x.tone}"><span class="attention-symbol">${icon(x.icon)}</span><div><strong>${x.rows.length} ${x.label}</strong>${['risks','escalations'].includes(x.key)?`<p title="${e(x.rows[0].name)}">${e(x.rows[0].name)}${x.rows.length>1?' · +'+(x.rows.length-1)+' more':''}</p>`:''}</div>${icon('arrow')}</a>`).join('')||`<div class="attention-clear">${icon('check')}<span>No open risks, decisions or missing confirmations.</span></div>`}</div></section>`;
}
function deliveryStatus(){return `<section class="analytics-panel delivery-status"><div class="panel-title"><h2>${icon('chart')}Delivery Status</h2></div><div class="delivery-status-rows">${['actions','milestones','rfp'].map((k,i)=>{const rows=active(k),completed=rows.filter(M.finished).length,percent=rows.length?Math.round(completed/rows.length*100):0;return `<a href="#${k}" class="delivery-status-row tone-${['success','info','violet'][i]}"><div class="delivery-status-label">${icon(pageInfo(k).icon)}<span>${['Action points','Milestones','RFPs'][i]}</span><strong aria-label="${rows.length?percent+'%':'No records'}">${rows.length?countText(percent)+'%':'—'}</strong></div><div class="delivery-full-bar" role="progressbar" aria-label="${e(pageInfo(k).short)} completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-valuetext="${completed} of ${rows.length} completed"><i style="width:${percent}%"></i></div><small>${completed} of ${rows.length} completed${k==='milestones'&&rows.some(r=>!r.status)?' · '+rows.filter(r=>!r.status).length+' to confirm':''}</small></a>`;}).join('')}</div></section>`;}
function milestoneCompletion(){const milestones=active('milestones'),groups=I.group(milestones,db.milestoneCategoryOrder||[]),done=milestones.filter(M.finished).length;return `<section class="analytics-panel category-chart"><div class="panel-title"><h2>Milestone Completion</h2><a href="#milestones" aria-label="Open milestone tracker">${done} / ${milestones.length}${icon('arrow')}</a></div><div class="category-bars">${groups.map(g=>`<a href="#milestones" title="${e(g.name)}: ${g.complete} of ${g.total} completed"><span>${e(g.name)}</span><div class="metric-track"><i style="width:${g.percent}%"></i></div><b>${g.complete}/${g.total}</b></a>`).join('')||'<p>No milestone categories yet.</p>'}</div></section>`;}
function agenda(){
 return `<div class="dashboard-heading"><div><span class="eyebrow">PULSE 5G / PROJECT WORKSPACE</span><h1>Project overview</h1></div><div class="button-row"><span class="agenda-save-state ${storageIssue?'has-warning':''}" role="status">${icon(storageIssue?'alert':'saved')}<span>${storageIssue?'Export a backup to keep changes':'Changes save in this browser'}</span></span><button class="settings-gear" data-action="settings" aria-label="Workspace settings" title="Settings">${icon('gear')}</button></div></div>${deliveryStatus()}<div class="dashboard-layout"><div class="dashboard-content"><section class="agenda-workspace" aria-label="Project areas"><div class="compact-agenda">${pages.map(agendaCard).join('')}</div></section><div class="dashboard-charts">${attentionPanel()}${milestoneCompletion()}</div></div><aside class="meeting-feed analytics-panel"><div class="feed-visual"><img src="assets/imagery/uae-network.png" alt="Conceptual UAE skyline and mobile-network infrastructure"><span>UAE / PRIVATE 5G</span></div><div class="panel-title"><h2>Latest project updates</h2>${icon('clock')}</div><div class="feed-scroll">${feed()}</div></aside></div>`;
}
function getRows(k){return I.filterRows(showDeleted?db.collections[k].filter(r=>r.deletedAt):active(k),S[k].fields,{query,status:filter,sort:sorts[k]});}
function view(k){return views[k]||'table';}
function actionOwner(r){const owner=r.owner?.trim();const initials=owner?owner.split(/[\s/]+/).slice(0,2).map(x=>Array.from(x)[0]).join('').toUpperCase():'';return `<span class="action-owner ${owner?'':'unassigned'}"><span class="owner-avatar" aria-hidden="true">${owner?e(initials):icon('user')}</span><span>${e(owner||'Unassigned')}${!owner?`<small>${icon('alert')} Owner needed</small>`:''}</span></span>`;}
function actionBadge(r){return `<span class="badge tone-${I.tone(r)}">${icon(M.finished(r)?'saved':r.status==='In Progress'?'clock':'alert')}${e(r.status||'Confirm status')}</span>`;}
function actionDates(r){return `<div class="action-dates"><span><small>Assigned</small><time>${r.assignedDate?e(date(r.assignedDate)):'—'}</time></span><span class="${r.closeDate?'has-date':''}"><small>Closed</small><time>${r.closeDate?e(date(r.closeDate)):'—'}</time></span></div>`;}
function actionAnalytics(){const rows=getRows('actions'),done=rows.filter(M.finished).length,owners=rows.filter(r=>r.owner?.trim()).length;return `<div class="action-insights"><div class="action-completion">${donut(done,rows.length,'complete','success',true)}<div><strong>${countText(done)}<small> / ${rows.length}</small></strong><span>Completed</span><small class="action-scope">${showDeleted?'Deleted actions':query||filter?'Filtered actions':'All actions'}</small></div></div><div class="action-mini tone-warning"><span class="action-mini-label">${icon('clock')} Active</span><strong>${countText(rows.length-done)}</strong><span>To complete</span></div><div class="action-mini tone-${owners<rows.length?'warning':'info'}"><span class="action-mini-label">${icon(owners<rows.length?'alert':'users')} Ownership</span><strong>${countText(owners)}<small> / ${rows.length}</small></strong><span>${owners<rows.length?(rows.length-owners)+' unassigned':'Owners assigned'}</span></div></div>`;}
function actionHeading(){return `<div class="page-heading action-heading with-visual"><div class="action-hero-art"><img src="about/assets/images/backgrounds/ad-ops-center.webp" alt="UAE network operations centre illustration"></div><div class="page-title"><div><div class="eyebrow">${icon('check')} PULSE 5G / 01</div><h1>Action Point Tracker</h1><p>Ownership. Progress. Follow-through.</p></div></div><div id="tracker-analytics">${actionAnalytics()}</div><div class="button-row">${btn('Export','export-page','excel','page-export')}${btn('Add action','add','plus','primary')}</div></div>`;}
function actionTable(list){return `<div class="table-wrap action-table-wrap" tabindex="0" role="region" aria-label="Action Point Tracker table"><table class="tracker-table action-table"><colgroup><col class="col-number"><col class="col-name"><col class="col-owner"><col class="col-status"><col class="col-remarks"><col class="col-dates"><col class="col-updates"><col class="col-tools"></colgroup><thead><tr><th scope="col">#</th><th scope="col">Action point</th><th scope="col">${icon('users')} Owner</th><th scope="col">Status</th><th scope="col">Remarks</th><th scope="col">${icon('calendar')} Dates</th><th scope="col">Project updates</th><th scope="col" aria-label="Edit"></th></tr></thead><tbody>${list.map((r,i)=>{const latest=r.updates.at(-1);return `<tr class="action-row tone-${I.tone(r)} ${M.finished(r)?'is-complete':''}" data-record="${e(r.id)}" data-flip-id="${e(r.id)}"><td class="cell-number">${String(i+1).padStart(2,'0')}</td><td><button class="row-name action-title" data-detail="${e(r.id)}" data-key="actions">${e(r.name)}</button></td><td>${actionOwner(r)}</td><td class="cell-status">${actionBadge(r)}</td><td><span class="cell-text action-remarks" title="${e(r.remarks||'')}">${e(r.remarks||'No remarks yet')}</span></td><td>${actionDates(r)}</td><td class="cell-history"><button data-detail="${e(r.id)}" data-key="actions">${icon(r.updates.length?'decision':'plus')}${r.updates.length?r.updates.length+' update'+(r.updates.length===1?'':'s'):'Add update'}</button>${latest?`<time class="latest-date">${e(date(latest.at))}</time>`:''}</td><td class="cell-tools">${r.deletedAt?`<button class="icon-button" data-restore="${e(r.id)}" data-key="actions" aria-label="Restore record">${icon('backup')}</button>`:`<button class="icon-button" data-edit="${e(r.id)}" data-key="actions" aria-label="Edit ${e(r.name)}">${icon('edit')}</button>`}</td></tr>`;}).join('')||`<tr><td colspan="8" class="empty-table"><span class="action-empty-icon">${icon(showDeleted?'trash':query||filter?'search':'check')}</span><h3>${showDeleted?'No deleted actions':query||filter?'No matching actions':'Ready for the next action'}</h3><p>${showDeleted?'Deleted actions can be restored here.':query||filter?'Adjust your search or reset the toolbar.':'Add an action to assign ownership and track progress.'}</p>${!showDeleted&&!query&&!filter?btn('Add action','add','plus','primary'):''}</td></tr>`}</tbody></table></div>`;}
function actionCard(r,i){const latest=r.updates.at(-1);return `<article class="record action-card tone-${I.tone(r)} ${M.finished(r)?'is-complete':''}" data-record="${e(r.id)}" data-flip-id="${e(r.id)}"><div class="record-top">${actionBadge(r)}<span class="record-id">${String(i+1).padStart(2,'0')}</span></div><div class="record-scroll"><h3><button class="action-title" data-detail="${e(r.id)}" data-key="actions">${e(r.name)}</button></h3>${actionOwner(r)}<p class="record-summary">${e(r.remarks||'No remarks yet.')}</p>${actionDates(r)}${latest?`<div class="latest-update"><small>${icon('decision')} ${e(date(latest.at))} · Latest update</small><p>${e(latest.text)}</p></div>`:''}</div><div class="record-bottom"><button class="history-button" data-detail="${e(r.id)}" data-key="actions">${icon(r.updates.length?'decision':'plus')} ${r.updates.length?'Updates · '+r.updates.length:'Add update'}</button>${r.deletedAt?`<button data-restore="${e(r.id)}" data-key="actions">Restore</button>`:`<button class="icon-button" data-edit="${e(r.id)}" data-key="actions" aria-label="Edit ${e(r.name)}">${icon('edit')}</button>`}</div></article>`;}
function trackerAnalytics(k){if(k==='actions')return actionAnalytics();const rows=getRows(k),complete=rows.filter(M.finished).length;return `<div class="tracker-insights"><div class="header-completion">${k==='escalations'?donut(rows.filter(r=>r.category==='Approval').length,rows.length,'approvals','violet'):donut(complete,rows.length,k==='risks'?'closed':'complete')}<div class="header-distribution"><div class="metric-caption"><b>${rows.length}</b><span>${showDeleted?'deleted':'active'} records</span></div><div class="segment-bar">${segments(k,rows)}</div><small>${k==='escalations'?rows.filter(r=>r.category==='Escalation').length+' escalations':complete+' '+(k==='risks'?'closed':'completed')+' · '+(rows.length-complete)+' remaining'}</small></div></div>${S[k].fields.some(f=>f.key==='owner')?`<div class="header-owner tone-${rows.some(r=>!r.owner)?'warning':'success'}">${icon('users')}<div><strong>${rows.filter(r=>r.owner).length} / ${rows.length}</strong><span>Owners assigned</span></div></div>`:''}</div>`;}
function sortOptions(k){return [['','Original order'],['name:asc','Name A–Z'],['name:desc','Name Z–A'],['modifiedAt:desc','Recently changed'],...(S[k].fields.some(f=>f.key==='owner')?[['owner:asc','Owner A–Z']]:[]),...(k==='milestones'?[['progress:desc','Progress high–low'],['completionDate:asc','Completion date']]:k==='actions'?[['assignedDate:asc','Assignment date']]:[])];}
function tracker(k){const s=S[k],status=s.fields.find(f=>f.key==='status'||f.key==='category'&&k==='escalations');return (k==='actions'?actionHeading():heading(k,btn('Add '+(k==='rfp'?'RFP':k==='risks'?'risk':k==='milestones'?'milestone':k==='actions'?'action':'item'),'add','plus','primary'),`<div id="tracker-analytics">${trackerAnalytics(k)}</div>`))+`<div class="filter-bar"><div class="filter-controls"><label class="search-control">${icon('search')}<input id="search" type="search" placeholder="Search ${e(s.short.toLowerCase())}…" aria-label="Search records" value="${e(query)}"></label><select id="status-filter" aria-label="Filter status or category"><option value="">All ${k==='escalations'?'categories':'statuses'}</option>${status.choices.map(c=>`<option ${filter===c?'selected':''}>${e(c)}</option>`).join('')}${k==='milestones'?`<option value="__blank__" ${filter==='__blank__'?'selected':''}>Unconfirmed</option>`:''}</select><select id="sort-choice" aria-label="Sort records">${sortOptions(k).map(([v,l])=>`<option value="${v}" ${v===(sorts[k]?sorts[k].key+':'+sorts[k].direction:'')?'selected':''}>${l}</option>`).join('')}</select><button class="reset-control" data-action="clear-filters" aria-label="Reset search and sorting" title="Reset">${icon('backup')}</button></div><div class="table-view-tools"><span id="record-count">${getRows(k).length} shown</span><div class="view-switch" role="group" aria-label="Record view">${(k==='milestones'?['categories','table','cards']:['table','cards']).map(v=>`<button data-action="view-${v}" class="${view(k)===v?'active':''}" aria-pressed="${view(k)===v}">${icon(v==='table'?'table':v==='categories'?'panels':'grid')}<span>${v==='categories'?'Categories':v==='table'?'Table':'Cards'}</span></button>`).join('')}</div><button class="deleted-control" data-action="toggle-deleted">${icon(showDeleted?'backup':'trash')}<span>${showDeleted?'Active':'Deleted'}</span></button></div></div><div id="records">${recordsHTML(k)}</div><p class="source-note">${k==='milestones'?'Category completion = completed milestones ÷ all active milestones in the category.':'Update timestamps: Gulf Standard Time (UTC+4).'}</p>`;
}
function recordsHTML(k){const list=getRows(k);if(view(k)==='table')return trackerTable(k,list);if(!list.length)return `<div class="empty">${icon(S[k].icon)}<h3>${showDeleted?'No deleted records':query||filter?'No matching records':'Ready for your next update'}</h3><p>${showDeleted?'Deleted items will remain recoverable here.':query||filter?'Try another search or status.':'Add a record, or import Excel from Settings.'}</p>${!showDeleted&&!query&&!filter?btn('Add record','add','plus','primary'):''}</div>`;
 if(k==='milestones'&&view(k)==='categories')return categoryCarousel(list);
 if(view(k)==='table')return trackerTable(k,list);
 return `<div class="record-grid ${k==='escalations'?'decisions':''}">${list.map((r,i)=>recordCard(k,r,i)).join('')}</div>`;
}
function trackerTable(k,list){
 if(k==='actions')return actionTable(list);
 const fields=S[k].fields;
 const widths={name:k==='escalations'?430:230,owner:150,status:115,category:k==='milestones'?150:125,remarks:230,impact:195,mitigation:220,reference:120,assignedDate:112,closeDate:112,completionDate:125,progress:90};
 const min=fields.reduce((sum,f)=>sum+(widths[f.key]||150),0)+230;
 function cell(f,r){const value=r[f.key]||'';
  if(f.key==='name')return `<button class="row-name" data-detail="${e(r.id)}" data-key="${k}">${e(r.name)}</button>${r.baselineProgress!=null?`<span class="cell-secondary">Previously reported: ${e(r.baselineProgress)}%</span>`:''}`;
  if(f.type==='select'&&(f.key==='status'||k==='escalations'))return badge(r);
  if(f.key==='progress')return `<div class="table-progress"><b>${I.progress(r)}%</b><div class="metric-track"><i style="width:${I.progress(r)}%"></i></div></div>`;
  if(f.type==='date')return `<span class="cell-text">${e(value?date(value):'Not set')}</span>`;
  return `<span class="cell-text cell-preview" title="${e(value)}">${e(value||'—')}</span>`;
 }
 return `<div class="table-wrap" tabindex="0" role="region" aria-label="${e(S[k].title)} table"><table class="tracker-table" style="min-width:${min}px"><colgroup><col style="width:36px">${fields.map(f=>`<col style="width:${widths[f.key]||150}px">`).join('')}<col style="width:150px"><col style="width:44px"></colgroup><thead><tr><th>#</th>${fields.map(f=>`<th scope="col">${e(f.label)}</th>`).join('')}<th scope="col">Project updates</th><th aria-label="Edit"></th></tr></thead><tbody>${list.map((r,i)=>{const latest=r.updates.at(-1);return `<tr class="tone-${I.tone(r)}" data-record="${e(r.id)}" data-flip-id="${e(r.id)}"><td class="cell-number">${String(i+1).padStart(2,'0')}</td>${fields.map(f=>`<td class="${f.key==='status'||k==='escalations'&&f.key==='category'?'cell-status':''}">${cell(f,r)}</td>`).join('')}<td class="cell-history"><button data-detail="${e(r.id)}" data-key="${k}">${icon('clock')}${r.updates.length?r.updates.length+' updates':'Add update'}</button>${latest?`<time class="latest-date">${e(date(latest.at))}</time><span class="latest-mini">${e(latest.text)}</span>`:''}</td><td class="cell-tools">${r.deletedAt?`<button class="icon-button" data-restore="${e(r.id)}" data-key="${k}" aria-label="Restore record">${icon('backup')}</button>`:`<button class="icon-button" data-edit="${e(r.id)}" data-key="${k}" aria-label="Edit ${e(r.name)}">${icon('edit')}</button>`}</td></tr>`;}).join('')||`<tr><td colspan="${fields.length+3}" class="empty-table">No matching records. Adjust search or status.</td></tr>`}</tbody></table></div>`;
}
function recordCard(k,r,i){if(k==='actions')return actionCard(r,i);const latest=r.updates.at(-1),decision=k==='escalations';return `<article class="record tone-${I.tone(r)} ${decision?'decision-card':''}" ${decision&&!showDeleted&&!query&&!filter?'draggable="true" data-draggable="true"':''} data-record="${e(r.id)}" data-flip-id="${e(r.id)}"><div class="record-top">${badge(r)}<span class="${decision?'decision-index':'record-id'}">${String(i+1).padStart(2,'0')}</span></div><div class="record-scroll"><h3>${e(r.name)}</h3>${k==='milestones'?`<div class="milestone-progress">${donut(I.progress(r),100,'progress',I.tone(r))}<span>${e(r.category||'Uncategorized')}<small>${e(r.completionDate?date(r.completionDate):'No completion date')}</small></span></div>`:''}${r.owner?`<div class="record-meta">${icon('users')}<span>${e(r.owner)}</span></div>`:''}${r.reference?`<div class="record-meta">${icon('file')}<span>${e(r.reference)}</span></div>`:''}${r.assignedDate||r.closeDate?`<div class="record-meta">${icon('calendar')}<span>${r.assignedDate?'Assigned '+e(date(r.assignedDate)):''}${r.closeDate?' · Closed '+e(date(r.closeDate)):''}</span></div>`:''}${k==='risks'?`<p class="record-summary"><strong>Impact</strong> · ${e(r.impact||'To be recorded')}</p><p class="record-summary"><strong>Mitigation</strong> · ${e(r.mitigation||'To be recorded')}</p>`:r.remarks?`<p class="record-summary">${e(r.remarks)}</p>`:''}${latest?`<div class="latest-update"><small>${e(date(latest.at))} · Latest update</small><p>${e(latest.text)}</p></div>`:''}</div><div class="record-bottom"><button class="history-button" data-detail="${e(r.id)}" data-key="${k}">${icon('clock')} ${r.updates.length?'Updates · '+r.updates.length:'Add update'}</button><div class="record-footer-actions">${r.deletedAt?`<button data-restore="${e(r.id)}" data-key="${k}">Restore</button>`:`${decision?`<button class="icon-button" data-move="-1" data-id="${e(r.id)}" aria-label="Move card earlier">←</button><button class="icon-button" data-move="1" data-id="${e(r.id)}" aria-label="Move card later">→</button>`:''}<button class="icon-button" data-edit="${e(r.id)}" data-key="${k}" aria-label="Edit ${e(r.name)}">${icon('edit')}</button>`}</div></div></article>`;}

function categoryCarousel(list){const allGroups=I.group(showDeleted?db.collections.milestones.filter(r=>r.deletedAt):active('milestones'),db.milestoneCategoryOrder||[]),groups=I.group(list,db.milestoneCategoryOrder||[]).map(g=>({...allGroups.find(full=>full.name===g.name),records:g.records}));return `<section class="category-browser"><div class="carousel-toolbar"><div><h2>Delivery workstreams</h2><span>${groups.length} categories · ${list.length} milestones shown</span></div><div class="carousel-controls"><span id="carousel-position"></span><button data-carousel="-1" aria-label="Previous milestone categories">←</button><button data-carousel="1" aria-label="Next milestone categories">→</button></div></div><div class="category-track" tabindex="0" role="region" aria-label="Milestone categories carousel">${groups.map((g,i)=>{const tone=g.percent===100?'success':g.inProgress?'warning':g.unconfirmed?'unconfirmed':'info',source=(db.milestoneCategorySources||[]).find(r=>r.category===g.name),index=allGroups.findIndex(x=>x.name===g.name);return `<article class="milestone-category tone-${tone}" data-category="${e(g.name)}"><div class="category-cover">${/procurement|sites/i.test(g.name)?`<img src="assets/imagery/${/sites/i.test(g.name)?'radio-deployment':'optical-core'}.png" alt="">`:`<span class="category-emblem">${icon(/team/i.test(g.name)?'users':/compliance|raci|approval/i.test(g.name)?'shield':'flag')}</span>`}<span>WORKSTREAM ${String(i+1).padStart(2,'0')}</span><div class="category-order"><button data-category-move="-1" data-category-name="${e(g.name)}" aria-label="Move ${e(g.name)} category earlier" ${showDeleted||index<=0?'disabled':''}>←</button><button data-category-move="1" data-category-name="${e(g.name)}" aria-label="Move ${e(g.name)} category later" ${showDeleted||index>=allGroups.length-1?'disabled':''}>→</button></div></div><div class="category-summary"><div><h3>${e(g.name)}</h3><small>${g.complete} of ${g.total} milestones completed</small>${g.unconfirmed?`<span class="review-label">${g.unconfirmed} statuses to confirm</span>`:''}</div>${donut(g.complete,g.total,'complete',tone)}</div><div class="category-milestones">${g.records.map(r=>`<div class="milestone-item tone-${I.tone(r)}"><div class="milestone-item-heading"><button data-detail="${e(r.id)}" data-key="milestones">${e(r.name)}</button><button class="icon-button" data-edit="${e(r.id)}" data-key="milestones" aria-label="Edit ${e(r.name)}">${icon('edit')}</button></div><div class="milestone-item-status">${badge(r)}<b>${I.progress(r)}%</b></div><div class="metric-track"><i style="width:${I.progress(r)}%"></i></div><small>${r.completionDate?e(date(r.completionDate)):r.updates.length?r.updates.length+' project updates':'No completion date'}</small></div>`).join('')}</div><div class="category-footer"><button data-add-category="${e(g.name)}">${icon('plus')} Add milestone</button>${source?`<button data-detail="${e(source.id)}" data-key="milestones" title="Category notes and earlier updates">Category history</button>`:''}</div></article>`;}).join('')}</div></section>`;}
function bindCarousel(){const track=$('.category-track');if(!track)return;const cards=[...track.children],gap=16;const step=(cards[0]?.offsetWidth||0)+gap;categoryPosition=Math.min(categoryPosition,Math.max(0,cards.length-1));track.scrollLeft=categoryPosition*step;const update=()=>{if(!track.isConnected||!$('#carousel-position'))return;const index=Math.round(track.scrollLeft/step),visible=Math.max(1,Math.round((track.clientWidth+gap)/step));$('#carousel-position').textContent=(index+1)+'–'+Math.min(cards.length,index+visible)+' / '+cards.length;document.querySelector('[data-carousel="-1"]').disabled=track.scrollLeft<=2;document.querySelector('[data-carousel="1"]').disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-3;categoryPosition=index;};track.onscroll=update;update();track.onkeydown=ev=>{if(ev.target===track&&['ArrowLeft','ArrowRight'].includes(ev.key)){ev.preventDefault();ev.stopPropagation();browseCategories(ev.key==='ArrowLeft'?-1:1);}};}
function browseCategories(delta){const track=$('.category-track');if(!track)return;const step=track.children[0].offsetWidth+16;track.scrollTo({left:track.scrollLeft+step*delta,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
function moveCategory(name,delta){if(!canEdit())return;const names=I.group(active('milestones'),db.milestoneCategoryOrder||[]).map(g=>g.name),from=names.indexOf(name),to=from+delta;if(from<0||to<0||to>=names.length)return;[names[from],names[to]]=[names[to],names[from]];db.milestoneCategoryOrder=names;M.log(db,'milestones','',name+' category moved to position '+(to+1),'reorder');save();categoryPosition=Math.max(0,to-1);render();}
function sourceDetail(r){const history=[...(r.updates||[]).map(u=>({...u,kind:'Project update'})),...db.audit.filter(a=>a.collection==='milestones'&&a.recordId===r.id).map(u=>({...u,kind:'Record change'}))].sort((a,b)=>b.at.localeCompare(a.at));openModal(r.category+' · category history',`<div class="reference-summary"><p>Earlier category notes and updates. Current completion is calculated from individual milestones.</p><strong>${r.baselineProgress!=null?e(r.baselineProgress)+'%':'Not provided'}</strong><span>Previously reported progress · ${e(date(db.baselineDate))}</span><p>Previous category status: ${e(r.status||'Not set')}</p><p>${e(r.remarks||'')}</p></div><h3>Earlier category updates</h3><div class="timeline">${history.map(u=>`<article class="timeline-entry"><small>${e(u.kind)} · ${e(timestamp(u.at))}</small><p>${e(u.text)}</p></article>`).join('')||'<p class="muted">No earlier category updates.</p>'}</div>`,`<button data-close>Close</button>`,'Milestone history');}

function assets(){const group=(title,items)=>`<div class="asset-group"><h2>${title}</h2><div class="asset-grid">${items.map(([value,label])=>`<button class="asset-card" data-asset="${e(label)}" data-value="${e(value)}"><strong>${value}</strong><span>${label}</span></button>`).join('')}</div></div>`;return heading('assets','',`<div class="reference-stats"><div>${icon('network')}<b>762</b><span>mobile sites</span></div><div>${icon('users')}<b>10K</b><span>devices</span></div></div>`)+`<div class="assets-layout"><div><div class="panel network-map"><img src="assets/ppt/network-map.jpg" alt="5G private network map of Abu Dhabi Island">${btn('Explore network map','map-zoom','network')}</div><p class="source-note">Abu Dhabi Island · Private network footprint.</p></div><div>${group('Mobile sites',[['365','Shared outdoor'],['257','Shared IBS'],['140','Dedicated VVIP']])}${group('Physical infrastructure',[['71','Shared mobile aggregation'],['31','Dedicated mobile aggregation'],['4','Pulse aggregation DC'],['2','IP core sites'],['2','Central data centers'],['10K','Devices']])}<section class="panel"><div class="section-heading" style="margin-top:0"><h2>Device mix</h2><small>10,000 devices</small></div><div class="mix-bar"><span style="width:10%;background:#ee576b"></span><span style="width:60%;background:#628fd4"></span><span style="width:10%;background:#d1a656"></span><span style="width:20%;background:#60b796"></span></div><div class="asset-grid four">${[['10%','Critical IoT'],['60%','Communication terminals'],['10%','Streaming'],['20%','Voice']].map(([v,l])=>`<button class="asset-card" data-asset="${l}" data-value="${v}"><strong>${v}</strong><span>${l}</span></button>`).join('')}</div></section></div></div><p class="source-note">Network inventory · 27 Feb 2026. These are not live device or network status readings.</p>`;}
function member(r){const group=active('team').filter(x=>x.group===r.group),index=group.findIndex(x=>x.id===r.id),tone=r.owner?'info':'warning',initials=(r.owner||'').split(/[\s,&]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();return `<div class="member tone-${tone}" data-team-id="${e(r.id)}" data-flip-id="${e(r.id)}" draggable="true"><span class="member-avatar">${initials?e(initials):icon('user')}</span><div class="member-copy"><div class="role">${e(r.name)}</div><div class="person">${e(r.owner||'Awaiting nomination')}</div></div><div class="member-tools"><button class="team-grip" draggable="true" aria-label="Reorder ${e(r.name)}" title="Drag within this group; use up/down arrows">${icon('grip')}</button><button data-team-move="-1" data-team-id="${e(r.id)}" aria-label="Move ${e(r.name)} earlier" ${index===0?'disabled':''}>${icon('up')}</button><button data-team-move="1" data-team-id="${e(r.id)}" aria-label="Move ${e(r.name)} later" ${index===group.length-1?'disabled':''}>${icon('down')}</button><button data-edit="${e(r.id)}" data-key="team" aria-label="Edit ${e(r.name)}">${icon('edit')}</button></div></div>`;}
function team(){const rows=active('team'),board=rows.filter(r=>r.group==='Governance Board');return heading('team',btn('Add role / member','add','plus','primary'),`<div class="reference-stats">${donut(rows.filter(r=>r.owner).length,rows.length,'nominated','info')}<div><b>${rows.length}</b><span>roles across 4 groups</span></div></div>`)+`<section class="team-board"><div class="group-heading"><h2>${icon('crown')}Governance Board</h2><span>${board.length} roles</span></div><div class="board-members" data-team-group="Governance Board">${board.map(member).join('')||'<p class="muted">No board members added.</p>'}</div></section><div class="team-columns">${['e& Business','e& Technology','Client'].map((g,i)=>{const list=rows.filter(r=>r.group===g);return `<section class="team-column"><div class="group-heading"><h2>${icon(['briefcase','network','users'][i])}${e(g)}</h2><span>${list.length} roles</span></div><div class="team-members" data-team-group="${e(g)}">${list.map(member).join('')||'<p class="muted">No workstreams added.</p>'}</div></section>`;}).join('')}</div><p class="source-note">${icon('grip')} Drag members within their group or use the move arrows. Unfilled roles retain their original nominations.</p>`;}
function moveTeam(id,targetId,delta){if(!canEdit())return;const r=db.collections.team.find(x=>x.id===id);if(!r)return;const next=I.reorderTeam(db.collections.team,id,targetId,delta);if(!next)return;const container=[...document.querySelectorAll('[data-team-group]')].find(x=>x.dataset.teamGroup===r.group);const state=container?PulseFX.capture(container):null;db.collections.team=next;M.log(db,'team',id,'Role reordered within '+r.group,'reorder');save();if(container){container.innerHTML=active('team').filter(x=>x.group===r.group).map(member).join('');bindTeamDrag();PulseFX.flip(state);container.querySelector(`[data-team-id="${CSS.escape(id)}"] .team-grip`)?.focus({preventScroll:true});}else render();}
function bindTeamDrag(){let dragged='';document.querySelectorAll('.member[data-team-id]').forEach(el=>{el.ondragstart=ev=>{if(ev.target.closest('button')&&!ev.target.closest('.team-grip')){ev.preventDefault();return;}dragged=el.dataset.teamId;ev.dataTransfer.setData('text/plain',dragged);ev.dataTransfer.effectAllowed='move';el.classList.add('dragging');};el.ondragend=()=>{dragged='';document.querySelectorAll('.member').forEach(n=>n.classList.remove('dragging','drag-over'));};el.ondragover=ev=>{if(!dragged)return;const source=db.collections.team.find(r=>r.id===dragged),target=db.collections.team.find(r=>r.id===el.dataset.teamId);if(source?.group!==target?.group)return;ev.preventDefault();ev.dataTransfer.dropEffect='move';el.classList.add('drag-over');};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=ev=>{ev.preventDefault();if(dragged)moveTeam(dragged,el.dataset.teamId);dragged='';el.classList.remove('drag-over');};});}

function raci(){const rows=active('raci'),unassigned=rows.filter(r=>![0,1,2,3].some(i=>r['role'+i].includes('A'))).length;return heading('raci',btn('Add activity','add','plus','primary'),`<div class="reference-stats">${donut(rows.length-unassigned,rows.length,'assigned','violet')}<div><b>${rows.length}</b><span>responsibility mappings</span></div></div>`)+`<div class="raci-legend"><span><b class="raci-R">R</b> Responsible</span><span><b class="raci-A">A</b> Accountable</span><span><b class="raci-C">C</b> Consulted</span><span><b class="raci-I">I</b> Informed</span><span><b>A/R</b> Both roles</span></div>${unassigned?`<div class="warning-note">${unassigned} activities have no accountable party assigned.</div>`:''}<div class="table-wrap"><table class="raci-table"><thead><tr><th>Activity</th><th>e&</th><th>Vendor</th><th>C42</th><th>Client</th><th aria-label="Edit activity"></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="name-cell">${e(r.name)}</td>${[0,1,2,3].map(i=>`<td><button class="raci-cell raci-${e(r['role'+i].replace('/',''))}" data-raci="${e(r.id)}" data-field="role${i}" aria-label="Edit ${e(S.raci.fields[i+1].label)} assignment for ${e(r.name)}">${e(r['role'+i]||'—')}</button></td>`).join('')}<td><button class="icon-button" data-edit="${e(r.id)}" data-key="raci" aria-label="Edit activity">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><p class="source-note">Click an assignment to edit it. Blank assignments remain unassigned. ${btn('Deleted activities','deleted-raci','trash','inline-link')}</p>`;}
function settings(){
 settingsOpen=true;pendingExcel=null;importGeneration++;
 openModal('Workspace settings',`<div class="settings-content"><section class="settings-section"><h3>Excel data</h3><p>Choose a tracker to import data. Each file is validated before any records are added.</p><div class="settings-imports">${tracks.map(k=>`<div class="settings-import-row"><div><strong>${e(S[k].short)}</strong><small>${active(k).length} active records</small></div><button data-import-key="${k}" aria-label="Import Excel for ${e(S[k].short)}">${icon('upload')} Import</button><a href="templates/${e(S[k].file)}" download="${e(S[k].file)}" class="template-link" aria-label="Download ${e(S[k].short)} template">${icon('excel')} Template</a></div>`).join('')}</div><p class="settings-note">Only the name/title is mandatory. Use the supplied headers; other fields can be filled in later. Excel imports append records.</p></section><section class="settings-section"><h3>Workspace backups & reports</h3><p>JSON preserves the full workspace, updates and arrangement. Excel provides a readable project report.</p><div class="settings-actions">${btn('Export JSON backup','export-json','backup')}${btn('Restore JSON backup','import-json','upload')}${btn('Export full Excel report','export-xlsx','excel')}</div></section><section class="settings-section"><h3>Recovery & deleted records</h3><div class="settings-actions">${btn('Recovery copy','recovery','backup')}${btn('Deleted records','deleted','trash')}</div><p class="settings-note">Changes save in this browser. Keep a JSON backup when moving to another device.</p></section></div>`,`<button data-close>Done</button>`,'Pulse 5G');
}
async function exportPage(button){const key=route;if(!pages.includes(key))return;button.disabled=true;try{const rows=S[key]?(tracks.includes(key)?getRows(key):active(key)):null;const scope=tracks.includes(key)?`${showDeleted?'Deleted':'Active'} records shown on page. Search and status applied; current sort order retained.`:'All active records on this page.';const blob=await PulseExcel.exportWorkbook(db,{page:key,records:rows,scope});download(blob,'Pulse-5G-'+key+'-'+filename('xlsx').replace('Pulse-5G-Updates-',''));toast('Excel exported for '+pageInfo(key).short+'.');}finally{if(button.isConnected)button.disabled=false;}}
function notifySaved(message){toast(storageIssue||message);}
function openModal(title,body,footer='',eyebrow='Project Updates'){PulseFX.closeSelect();if(!$('#modal').open)lastFocus=document.activeElement;if(settingsOpen&&title!=='Workspace settings')footer=btn('Back to Settings','settings','arrow')+footer;$('#modal').classList.remove('modal-map');$('#modal-content').innerHTML=`<div class="modal-header"><div><div class="eyebrow">${e(eyebrow)}</div><h2>${e(title)}</h2></div><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();PulseFX.modal($('#modal'));}
function closeModal(){PulseFX.closeSelect();$('#modal').close();pendingExcel=null;settingsOpen=false;importGeneration++;}
function fieldHTML(f,value){return `<label class="${f.type==='textarea'||f.key==='name'?'wide':''}">${e(f.label)}${f.key==='name'?' *':''}${f.type==='select'?`<select name="${f.key}">${!value&&!f.choices.includes('')?'<option value="">Confirm status…</option>':''}${f.choices.map(c=>`<option value="${e(c)}" ${value===c?'selected':''}>${e(c||'Unassigned')}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.key}" maxlength="30000">${e(value)}</textarea>`:`<input name="${f.key}" type="${f.type}" value="${e(value)}" ${f.type==='number'?'min="0" max="100" step="1"':''} ${f.key==='name'?'required maxlength="500"':'maxlength="30000"'}>`}</label>`;}
function edit(k,id,focusField){if(!canEdit())return;const r=id?db.collections[k].find(r=>r.id===id):M.defaults(k);if(!r)return;const fields=S[k].fields;openModal((id?'Edit ':'Add ')+({'actions':'action point',risks:'risk',rfp:'RFP',milestones:'milestone',escalations:'escalation / approval',team:'role / member',raci:'activity'}[k]),`<form id="edit-form" data-key="${k}" data-id="${e(id||'')}"><div class="form-grid">${fields.map(f=>fieldHTML(f,r[f.key]||'')).join('')}</div><p class="form-error" id="form-error" role="alert"></p><small class="muted">* Name/title is required. Changes are recorded automatically.</small></form>`,`${id?`<button class="delete-button" data-delete="${e(id)}" data-key="${k}">Delete record</button>`:''}<button data-close>Cancel</button><button class="primary" type="submit" form="edit-form">Save record</button>`,S[k].title);if(focusField){const f=$('#edit-form [name="'+focusField+'"]');(f.closest('.glass-select')?.querySelector('button')||f).focus();}}
function saveForm(form){if(!canEdit())return;const k=form.dataset.key,id=form.dataset.id,values=Object.fromEntries(new FormData(form));for(const key in values)values[key]=values[key].trim();if(!values.name){$('#form-error').textContent='Enter a name/title.';return;}if(k==='actions'&&values.assignedDate&&values.closeDate&&values.closeDate<values.assignedDate){$('#form-error').textContent='Close Date cannot precede Assign Date.';return;}
 if(k==='milestones'){if(values.progress!==''&&(!Number.isFinite(Number(values.progress))||Number(values.progress)<0||Number(values.progress)>100)){$('#form-error').textContent='Progress must be between 0 and 100.';return;}if(values.status==='Completed')values.progress='100';if(values.status==='Not Started')values.progress='0';}
 for(const f of S[k].fields){if(f.type==='date'&&values[f.key]&&!M.validDate(values[f.key])){$('#form-error').textContent='Enter a valid '+f.label+'.';return;}}
 if(id){const r=db.collections[k].find(r=>r.id===id);if(k==='milestones'&&values.status)r.statusReviewRequired=false;const changes=S[k].fields.filter(f=>values[f.key]!==r[f.key]).map(f=>`${f.label}: ${r[f.key]||'blank'} → ${values[f.key]||'blank'}`);if(changes.length){Object.assign(r,values,{modifiedAt:M.now()});M.log(db,k,id,changes.join('\n'));}}
 else{const r=M.newRecord(k,values);db.collections[k].push(r);M.log(db,k,r.id,'Record added: '+r.name,'create');}save();closeModal();render();notifySaved('Record saved.');}
function detail(k,id){const r=db.collections[k].find(r=>r.id===id)||(k==='milestones'?(db.milestoneCategorySources||[]).find(r=>r.id===id):null);if(!r)return;if(r.milestoneExpanded){sourceDetail(r);return;}const history=[...r.updates.map(u=>({...u,type:'update'})),...db.audit.filter(a=>a.collection===k&&a.recordId===id).map(a=>({...a,type:'audit'}))].sort((a,b)=>b.at.localeCompare(a.at));let currentDay='';const timeline=history.map(u=>{const d=date(u.at),head=d!==currentDay?`<div class="day-label">${e(d)}</div>`:'';currentDay=d;return head+`<article class="timeline-entry ${u.type==='audit'?'audit':''}"><div class="entry-header"><span>${u.type==='update'?'Project update':'Record change'}${u.author?' · '+e(u.author):''}</span><time>${e(timestamp(u.at))}</time></div><p>${e(u.text)}</p></article>`;}).join('');
 const extras=[r.remarks&&!S[k].fields.some(f=>f.key==='remarks')?['Additional details',r.remarks]:null,r.expectedCompletion?['Expected completion',r.expectedCompletion]:null,r.baselineProgress!=null?['Previously reported progress',r.baselineProgress+'%']:null,...Object.entries(r.extraFields||{})].filter(Boolean);
 openModal(r.name,`<dl class="detail-fields">${S[k].fields.filter(f=>f.key!=='name').map(f=>`<div class="${f.type==='textarea'?'wide':''}"><dt>${e(f.label)}</dt><dd>${e(r[f.key]||'Not set')}</dd></div>`).join('')}${extras.map(([k,v])=>`<div class="wide"><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><section class="detail-section"><h3>Project updates & history</h3>${!r.deletedAt?`<form class="update-form" id="update-form" data-key="${k}" data-id="${e(id)}"><textarea name="text" aria-label="Project update" placeholder="What changed? Record progress, decisions or next steps…" required maxlength="30000"></textarea><div class="button-row"><input name="author" aria-label="Updated by (optional)" placeholder="Updated by (optional)" maxlength="120"><button type="submit" class="primary">${icon('plus')} Add update</button></div></form>`:'<p class="warning-note">This record is deleted. Restore it to add updates.</p>'}<div class="timeline">${timeline||'<p class="muted">No project updates or changes yet.</p>'}</div></section>`,r.deletedAt?`<button data-restore="${e(id)}" data-key="${k}">Restore record</button>`:`<button data-edit="${e(id)}" data-key="${k}">Edit record / status</button><button data-close>Close</button>`,S[k].title);
}
function addUpdate(form){if(!canEdit())return;const text=form.elements.text.value.trim();if(!text)return;const k=form.dataset.key,id=form.dataset.id,r=db.collections[k].find(r=>r.id===id);r.updates.push({id:M.uid(),at:M.now(),text,author:form.elements.author.value.trim()});r.modifiedAt=M.now();save();render();detail(k,id);notifySaved('Update added to the dated project history.');}
function remove(k,id){if(!canEdit())return;const r=db.collections[k].find(r=>r.id===id);openModal('Delete this record?',`<p class="overflow-text">${e(r.name)}</p><p class="meeting-note" style="margin-top:16px">The record and its history will move to Deleted records. You can restore it later.</p>`,`<button data-close>Cancel</button><button class="primary" data-confirm-delete="${e(id)}" data-key="${k}">Delete record</button>`);}
function restore(k,id){if(!canEdit())return;const r=db.collections[k].find(r=>r.id===id);delete r.deletedAt;M.log(db,k,id,'Record restored','restore');save();closeModal();render();notifySaved('Record restored.');}
function deletedModal(only){const keys=only?[only]:Object.keys(S);const rows=keys.flatMap(k=>db.collections[k].filter(r=>r.deletedAt).map(r=>({k,r})));openModal('Deleted records',rows.length?rows.map(({k,r})=>`<div class="recent-row"><div>${icon(S[k].icon)}</div><div><p>${e(r.name)}</p><small>${e(S[k].short)} · Deleted ${e(date(r.deletedAt))}</small></div><button data-restore="${e(r.id)}" data-key="${k}">Restore</button></div>`).join(''):'<p class="meeting-note">There are no deleted records.</p>');}
function reorder(id,targetId,delta){if(!canEdit())return;sorts.escalations=null;const flipState=PulseFX.capture($('#records')),all=db.collections.escalations,list=active('escalations'),from=list.findIndex(r=>r.id===id);let to=targetId?list.findIndex(r=>r.id===targetId):from+delta;if(to<0||to>=list.length||to===from)return;const [item]=list.splice(from,1);list.splice(to,0,item);db.collections.escalations=[...list,...all.filter(r=>r.deletedAt)];M.log(db,'escalations',id,'Card moved to position '+(to+1),'reorder');save();render();PulseFX.flip(flipState);}
function bindPage(){if($('#search'))$('#search').oninput=ev=>{query=ev.target.value;refreshRecords();};if($('#status-filter'))$('#status-filter').onchange=ev=>{filter=ev.target.value;refreshRecords();};if($('#sort-choice'))$('#sort-choice').onchange=ev=>{const [key,direction]=ev.target.value.split(':');sorts[route]=key?{key,direction}:null;refreshRecords();};bindCarousel();bindDrag();bindTeamDrag();}
function refreshRecords(){$('#records').innerHTML=recordsHTML(route);$('#record-count').textContent=getRows(route).length+' shown';$('#tracker-analytics').innerHTML=trackerAnalytics(route);bindCarousel();bindDrag();if(route==='actions')PulseFX.actionsRefresh($('#main'));}
function bindDrag(){let dragged='';document.querySelectorAll('.record[draggable=true]').forEach(el=>{el.ondragstart=ev=>{dragged=el.dataset.record;ev.dataTransfer.setData('text/plain',dragged);ev.dataTransfer.effectAllowed='move';el.classList.add('dragging');};el.ondragend=()=>document.querySelectorAll('.record').forEach(n=>n.classList.remove('dragging','drag-over'));el.ondragover=ev=>{if(dragged){ev.preventDefault();el.classList.add('drag-over');}};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=ev=>{ev.preventDefault();if(dragged)reorder(dragged,el.dataset.record);dragged='';};});}
async function importExcel(file,key=importKey){const generation=++importGeneration;try{if(!tracks.includes(key))throw Error('Choose a tracker in Settings.');const book=await PulseExcel.open(file);if(generation!==importGeneration||!settingsOpen)return;pendingExcel={book,file,key,previewSeq:0};openModal('Import '+S[key].short,`<p class="meeting-note">${e(file.name)} · ${e(S[key].title)}</p><p class="meeting-note">Select a worksheet. Headers and every row are checked before your tracker changes.</p><label class="import-mapping">Worksheet <select id="sheet-choice">${book.sheets.map((s,i)=>`<option value="${i}">${e(s.name)}</option>`).join('')}</select></label><div id="excel-preview"></div>`);$('#sheet-choice').onchange=previewSheet;PulseFX.enhance($('#modal'));await previewSheet();}catch(err){if(generation===importGeneration)toast(err.message);}}
async function previewSheet(){const pending=pendingExcel;if(!pending)return;const preview=$('#excel-preview'),seq=++pending.previewSeq;pending.result=null;preview.innerHTML='<p class="meeting-note">Checking worksheet…</p>';try{const index=Number($('#sheet-choice').value),rows=await pending.book.read(index);if(pending!==pendingExcel||seq!==pending.previewSeq)return;const result=PulseExcel.validate(rows,pending.key,db.collections[pending.key]);pending.result=result;pending.sheet=pending.book.sheets[index].name;preview.innerHTML=`<div class="import-summary"><span class="badge done">${result.records.length} valid rows</span><span class="badge risk">${result.errors.length} errors</span><span class="badge">${result.duplicates.length} duplicates</span></div>${result.errors.length?`<p class="warning-note">Fix the errors in Excel and upload again. No rows have been imported.</p><ul class="validation-list">${result.errors.slice(0,100).map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}${result.warnings.length?`<ul class="validation-list">${result.warnings.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}<p class="import-mapping">Matched headers: ${result.mapping.map(m=>e(m.field.label)).join(', ')||'None'}</p>${result.records.length?`<div class="import-preview"><table><thead><tr><th>Excel row</th><th>Name / Title</th><th>Status / Category</th></tr></thead><tbody>${result.records.slice(0,8).map(r=>`<tr><td>${r.row}${r.duplicate?' · Duplicate':''}</td><td>${e(r.values.name)}</td><td>${e(r.values.status||r.values.category||'')}</td></tr>`).join('')}</tbody></table></div>`:''}${result.duplicates.length?'<label class="import-mapping" style="display:block;margin-top:15px">Duplicate names <select id="duplicate-policy"><option value="skip">Skip duplicate names</option><option value="add">Add as separate records</option></select></label>':''}<div class="button-row" style="margin-top:20px"><button class="primary" data-action="confirm-excel" ${result.errors.length||!result.records.length?'disabled':''}>Import validated rows</button><button data-close>Cancel</button></div>`;PulseFX.enhance(preview);}catch(err){if(pending!==pendingExcel||seq!==pending.previewSeq)return;pending.result=null;preview.innerHTML=`<p class="warning-note">${e(err.message)}</p>`;}}
function confirmExcel(){if(!canEdit()||!pendingExcel?.result||pendingExcel.result.errors.length)return;const {result,key,file,sheet}=pendingExcel,skip=$('#duplicate-policy')?.value!=='add';const records=result.records.filter(r=>!skip||!r.duplicate);if(!records.length){toast('All rows are duplicates. Nothing imported.');return;}if(!checkpoint())return;for(const row of records){const r=M.newRecord(key,row.values,{file:file.name,sheet,row:row.row,date:new Date().toISOString().slice(0,10)});db.collections[key].push(r);M.log(db,key,r.id,'Imported from '+file.name+' · '+sheet+' · row '+row.row,'import');}save();render();settings();notifySaved(records.length+' records imported into '+S[key].short+'.');}
async function importJSON(file){const generation=++importGeneration;try{if(file.size>25*1024*1024)throw Error('Choose a snapshot smaller than 25 MB.');const staged=M.normalize(JSON.parse(await file.text()));if(generation!==importGeneration||!settingsOpen)return;const rows=Object.keys(S).map(k=>`<tr><td>${e(S[k].short)}</td><td>${active(k).length}</td><td>${M.active(staged,k).length}</td></tr>`).join('');openModal('Restore project snapshot',`<p class="meeting-note">This replaces the current tracker, team, RACI and history with the selected snapshot. Export your current snapshot first if you want to keep both.</p><p class="source-note">${e(file.name)}${staged.exportedAt?' · Exported '+e(timestamp(staged.exportedAt)):''}</p><div class="import-preview"><table><thead><tr><th>Section</th><th>Current</th><th>Snapshot</th></tr></thead><tbody>${rows}</tbody></table></div>`,`${btn('Export current JSON','export-json','download')}<button data-close>Cancel</button><button id="confirm-json" class="primary">Restore snapshot</button>`);$('#confirm-json').onclick=()=>{if(!canEdit()||!checkpoint())return;db=staged;M.log(db,'snapshot','','Project snapshot restored: '+file.name,'restore');save();render();settings();notifySaved('Snapshot restored, including updates and card order.');};}catch(err){toast(err.message);}}
function recovery(){try{const previous=localStorage.getItem(PREVIOUS);if(!previous){toast('No recovery copy yet. One is saved before Excel imports and snapshot restores.');return;}const staged=M.normalize(JSON.parse(previous));openModal('Recovery copy',`<p class="meeting-note">A recovery copy is available from before the last import or restore. Download it to keep a backup, or restore it to this browser.</p><p class="source-note">Last saved: ${staged.modifiedAt?e(timestamp(staged.modifiedAt)):'Initial project data'}</p>`,`<button id="download-recovery">Download JSON</button><button id="restore-recovery" class="primary">Restore recovery copy</button>`);$('#download-recovery').onclick=()=>download(new Blob([JSON.stringify(staged,null,2)],{type:'application/json'}),'Pulse-5G-Recovery.json');$('#restore-recovery').onclick=()=>{if(!canEdit()||!checkpoint())return;db=staged;save();render();settings();notifySaved('Recovery copy restored.');};}catch(err){toast('Recovery copy is unavailable: '+err.message);}}
function recentModal(){const updates=tracks.flatMap(k=>active(k).flatMap(r=>r.updates.map(u=>({...u,key:k,name:r.name,recordId:r.id})))).sort((a,b)=>b.at.localeCompare(a.at));openModal('Recent project updates',updates.length?updates.slice(0,40).map(u=>`<div class="recent-row">${icon(S[u.key].icon)}<div><button class="inline-link" data-detail="${e(u.recordId)}" data-key="${u.key}">${e(u.name)}</button><p class="overflow-text">${e(u.text)}</p><small>${e(S[u.key].short)}${u.author?' · '+e(u.author):''}</small></div><time>${e(timestamp(u.at))}</time></div>`).join(''):'<p class="meeting-note">No project updates yet. Open a record and choose Add update to start its dated history.</p>');}
function mapZoom(){openModal('5G private network map','<div class="map-zoom"><img src="assets/ppt/network-map.jpg" alt="Abu Dhabi Island private network map"></div>',btn('Zoom in / out','map-toggle','network'));$('#modal').classList.add('modal-map');}
function sendAbout(){if(!route.startsWith('about-'))return;$('#about-frame').contentWindow?.postMessage({type:'pulse-shell',slide:Number(route.split('-')[1]),theme,lang:aboutLang},'*');}
function navigate(){let next=location.hash.slice(1)||'agenda';if(!['agenda',...pages,...aboutTitles.map((_,i)=>'about-'+(i+1))].includes(next))next='agenda';navDirection=orderedPages.indexOf(next)>=orderedPages.indexOf(route)?1:-1;route=next;query='';filter='';showDeleted=false;closeMenu();if($('#modal').open)closeModal();render();window.scrollTo(0,0);}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('button,a');if(!b)return;
 if(b.dataset.importKey){if(!canEdit())return;importKey=b.dataset.importKey;$('#excel-file').click();return;}
 if(b.matches('[data-close]')){closeModal();return;}
 if(b.dataset.edit){edit(b.dataset.key,b.dataset.edit);return;}
 if(b.dataset.detail){detail(b.dataset.key,b.dataset.detail);return;}
 if(b.dataset.delete){remove(b.dataset.key,b.dataset.delete);return;}
 if(b.dataset.confirmDelete){if(!canEdit())return;const r=db.collections[b.dataset.key].find(r=>r.id===b.dataset.confirmDelete);r.deletedAt=M.now();M.log(db,b.dataset.key,r.id,'Record deleted (recoverable)','delete');save();closeModal();render();notifySaved('Record moved to Deleted records.');return;}
 if(b.dataset.restore){restore(b.dataset.key,b.dataset.restore);return;}
 if(b.dataset.move){reorder(b.dataset.id,null,Number(b.dataset.move));return;}
 if(b.dataset.teamMove){moveTeam(b.dataset.teamId,null,Number(b.dataset.teamMove));return;}
 if(b.dataset.statusChoice){filter=filter===b.dataset.statusChoice?'':b.dataset.statusChoice;render();return;}
 if(b.dataset.carousel){browseCategories(Number(b.dataset.carousel));return;}
 if(b.dataset.categoryMove){moveCategory(b.dataset.categoryName,Number(b.dataset.categoryMove));return;}
 if(b.dataset.addCategory){edit('milestones');$('#edit-form [name=category]').value=b.dataset.addCategory;return;}
 if(b.dataset.raci){edit('raci',b.dataset.raci,b.dataset.field);return;}
 if(b.dataset.asset){openModal(b.dataset.asset,`<div class="stat" style="margin-bottom:20px"><strong>${e(b.dataset.value)}</strong><span>${e(b.dataset.asset)}</span></div><p class="meeting-note">${b.dataset.asset==='Devices'?'CPE, IoT and terminals.':b.dataset.asset==='Communication terminals'?'Communication terminals represent 60% of the device mix.':''}</p><p class="source-note">Network inventory dated 27 Feb 2026.</p>`);return;}
 const a=b.dataset.action;if(!a)return;
 try{switch(a){case 'settings':settings();break;case 'export-page':await exportPage(b);break;case 'view-categories':views[route]='categories';render();break;case 'clear-filters':query='';filter='';sorts[route]=null;render();break;case 'view-table':views[route]='table';render();break;case 'view-cards':views[route]='cards';render();break;case 'recent-updates':recentModal();break;case 'open-actions':location.hash='actions';break;case 'open-about':location.hash='about-1';break;case 'add':edit(route);break;case 'toggle-deleted':showDeleted=!showDeleted;render();break;case 'deleted':deletedModal();break;case 'deleted-team':deletedModal('team');break;case 'deleted-raci':deletedModal('raci');break;case 'export-json':exportJSON();break;case 'import-json':$('#json-file').click();break;case 'export-xlsx':b.disabled=true;toast('Preparing the project workbook…');download(await PulseExcel.exportWorkbook(db),filename('xlsx'));b.disabled=false;toast('Single-sheet project workbook exported.');break;case 'confirm-excel':confirmExcel();break;case 'recovery':recovery();break;case 'map-zoom':mapZoom();break;case 'map-toggle':$('.map-zoom').classList.toggle('zoomed');break;}}catch(err){b.disabled=false;toast(err.message);}
});
document.addEventListener('submit',ev=>{if(ev.target.id==='edit-form'){ev.preventDefault();saveForm(ev.target);}if(ev.target.id==='update-form'){ev.preventDefault();addUpdate(ev.target);}});
$('#excel-file').onchange=ev=>{const file=ev.target.files[0];ev.target.value='';if(file)importExcel(file);};$('#json-file').onchange=ev=>{const file=ev.target.files[0];ev.target.value='';if(file)importJSON(file);};
$('#page-previous').onclick=()=>stepPage(-1);$('#page-next').onclick=()=>stepPage(1);
document.addEventListener('click',ev=>{if(!ev.target.closest('.navigation-menu,.shell-header nav'))closeMenu();});
$('#theme').innerHTML=icon(theme==='dark'?'sun':'moon');$('#fullscreen').innerHTML=icon('expand');$('#page-previous').innerHTML=icon('left');$('#page-next').innerHTML=icon('arrow');
$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';document.body.classList.toggle('light',theme==='light');$('#theme').innerHTML=icon(theme==='dark'?'sun':'moon');try{localStorage.setItem(STORE+'-theme',theme);}catch(_){}sendAbout();};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use your browser’s full-screen or Add to Home Screen option.');}catch(_){toast('Full screen is unavailable in this browser.');}};
$('#about-frame').onload=sendAbout;
$('#about-language').onclick=()=>{aboutLang=aboutLang==='en'?'ar':'en';$('#about-language').textContent=aboutLang==='en'?'العربية':'English';sendAbout();};
$('#about-previous').onclick=()=>{const n=Number(route.split('-')[1]);location.hash=n<=1?'raci':'about-'+(n-1);};$('#about-next').onclick=()=>{const n=Number(route.split('-')[1]);location.hash=n>=6?'agenda':'about-'+(n+1);};
window.addEventListener('message',ev=>{if(ev.source!==$('#about-frame').contentWindow)return;const d=ev.data;if(d?.type==='pulse-about-agenda'&&route.startsWith('about-'))location.hash='agenda';if(d?.type==='pulse-about-slide'&&route.startsWith('about-')&&Number.isInteger(d.slide)&&d.slide>=1&&d.slide<=6&&route!=='about-'+d.slide)location.hash='about-'+d.slide;});
$('#modal').addEventListener('close',()=>{settingsOpen=false;pendingExcel=null;importGeneration++;PulseFX.closeSelect();if(lastFocus?.isConnected)lastFocus.focus();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();if(ev.target.closest('input,textarea,select,button,[role=combobox],[role=listbox],[contenteditable=true]')||$('#modal').open)return;if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){if(ev.target.closest('.table-wrap'))return;ev.preventDefault();stepPage(ev.key==='ArrowRight'?1:-1);return;}if(ev.key==='PageDown'||ev.key==='PageUp'){ev.preventDefault();const order=['agenda',...pages,...aboutTitles.map((_,i)=>'about-'+(i+1))],idx=order.indexOf(route);location.hash=order[(idx+(ev.key==='PageDown'?1:-1)+order.length)%order.length];}});
window.addEventListener('storage',ev=>{if(ev.key===STORE&&ev.newValue){try{const newer=JSON.parse(ev.newValue);if((newer.modifiedAt||'')!==loadedRevision){stale=true;storageIssue='This workspace was updated in another tab. Reload to use its latest data before editing.';render();}}catch(_){}}});
window.addEventListener('beforeunload',ev=>{if(storageIssue&&!stale){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('resize',()=>{if(route==='milestones'&&view(route)==='categories')bindCarousel();});
window.addEventListener('hashchange',navigate);navigate();
})();
